class Solution {
    int rows,cols,stateBase;
    unordered_map<long long,int> memo;
    int pairScore(int first,int second){
        if(!first||!second)return 0;
        if(first==1&&second==1)return -60;
        if(first==2&&second==2)return 40;
        return -10;
    }
    int dfs(int position,int mask,int intro,int extro){
        if(position==rows*cols)return 0;
        long long key=(((1LL*position*stateBase+mask)*7+intro)*7+extro);
        if(memo.count(key))return memo[key];
        int divisor=stateBase/3,up=mask/divisor,left=position%cols?mask%3:0,nextBase=mask%divisor*3;
        int best=dfs(position+1,nextBase,intro,extro);
        if(intro)best=max(best,120+pairScore(1,up)+pairScore(1,left)+dfs(position+1,nextBase+1,intro-1,extro));
        if(extro)best=max(best,40+pairScore(2,up)+pairScore(2,left)+dfs(position+1,nextBase+2,intro,extro-1));
        return memo[key]=best;
    }
    public:int getMaxGridHappiness(int m,int n,int introvertsCount,int extrovertsCount){
        rows=m;
        cols=n;
        stateBase=1;
        for(int i=0;i<n;++i)stateBase*=3;
        memo.clear();
        return dfs(0,0,introvertsCount,extrovertsCount);
    }
};
